CREATE TRIGGER task_parent_scope_insert BEFORE INSERT ON tasks WHEN NEW.parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM tasks WHERE id=NEW.parent_id AND org_id=NEW.org_id AND project_id=NEW.project_id) BEGIN SELECT RAISE(ABORT,'Task parent outside project'); END;
CREATE TRIGGER task_parent_scope_update BEFORE UPDATE OF parent_id,project_id,org_id ON tasks WHEN NEW.parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM tasks WHERE id=NEW.parent_id AND org_id=NEW.org_id AND project_id=NEW.project_id) BEGIN SELECT RAISE(ABORT,'Task parent outside project'); END;
