CREATE TRIGGER folder_parent_scope_update BEFORE UPDATE OF parent_id ON folders WHEN NEW.parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM folders WHERE id=NEW.parent_id AND org_id=NEW.org_id AND project_id=NEW.project_id) BEGIN SELECT RAISE(ABORT,'Folder parent outside project'); END;
