CREATE TRIGGER document_folder_scope_update BEFORE UPDATE OF folder_id ON documents WHEN NEW.folder_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM folders WHERE id=NEW.folder_id AND org_id=NEW.org_id AND project_id=NEW.project_id) BEGIN SELECT RAISE(ABORT,'Document folder outside project'); END;
